Method.Implementation:
	set daObj = ##class(%DynamicObject).%New()

	// WRITE !, "- ParseAllNodes: NodeData="_node.NodeData
	set prevNode = ""
	set dcObj = ""
	DO
	 {
		 set stat = $$$OK
		// Remove While elements
		while ((stat) && (node.NodeType = $$$xmlWHITESPACENODE))
    	{
	    	set stat = node.MoveToNextSibling()
    	}
    	if (stat)
    	{
			$$$TRACE( "- ParseAllNodes: NodeData="_node.NodeData _ " NodeType="_node.NodeType_" QName="_node.QName_" HasChildNodes returns "_node.HasChildNodes()_" GetNumberAttributes returns "_node.GetNumberAttributes())

			 Set count=node.GetNumberAttributes()
			 if (count >= 1)
			 {

			    $$$TRACE( " -- NodeData="_node.NodeData _ "_ Number of attributes: "_ count)
			    Set next=node.FirstAttributeName()

			    For i=1:1:count {
				    set val = node.GetAttributeValue(next)
			        $$$TRACE( "  -- Attribute " _ i _ ". "_ next _ "_ value is: "_ val)
			        set attrArray("@"_next) = val
			        Set next=node.NextAttributeName(next)
			    }
			}
	        if (node.NodeType = $$$xmlELEMENTNODE)
	        {
		        set text = ""
		    	Set status=node.GetText(.text)
		    	If status {
		        	$$$TRACE( "  -- ParseAllNodes:xmlELEMENTNODE: " _ node.NodeData _ ", text of the node is "_text	)        
		        	// WRITE !, node.NodeData _ ", text of the node is "_text
		        	// Do daObj.%Set(, text)
		    	}
	        }
	        if (node.HasChildNodes())
		    {
			    set callParseNode = 0
			    Do node.MoveToFirstChild()

				if ( (node.NodeType = $$$xmlELEMENTNODE) || (first = 1))
				{
					set callParseNode = 1
				}
				Do node.MoveToParent()
				if (callParseNode = 1)
				{
			    	// WRITE !, "Call ParseChildNode" _ node
		    		set dcObj = ..ParseChildNode(node, first, listArr )
		    		$$$TRACE( "   =From ParseChildNode= Node: " _ node.NodeData _ ", " _ dcObj)
				}
				else
				{
					set dcObj = text
				}

		    }
		    else
		    {
			    set dcObj = ""
		    }
		    if (prevNode = node.NodeData)
		    {

			    set prevObj = daObj.%Get(prevNode)
			    $$$TRACE( "  === CREATE ARRAY: " _ prevNode )
			    IF ( ($$$IsdefObject(prevObj)) && (prevObj.%IsA("%Library.DynamicArray")) )
				{
					set dynArray = prevObj
				}
				else
				{
			    	set dynArray = ##class(%DynamicArray).%New()
			    	Do dynArray.%Push(prevObj)
			    	Do daObj.%Remove(prevObj)
				}

			    Do dynArray.%Push(dcObj)
			    $$$TRACE( dynArray)
			    set iter = dynArray.%GetIterator()
		   			while iter.%GetNext(.key , .value ) {
		      		$$$TRACE( "Array: key = "_key_" , value = "_value)
		   		}
		   		Do daObj.%Set(node.NodeData, dynArray)
		    }
		    elseif ($LISTFIND(listArr, node.NodeData) >= 1)
		    {
			    // Calling function sent names of nodes that should be created as ARRAY
			    $$$TRACE( "  === CREATE ARRAY: " _ node.NodeData _ " -LF: " _ $LISTFIND(listArr, node.NodeData))
			    set dynArray = ##class(%DynamicArray).%New()
			    Do dynArray.%Push(dcObj)
			    Do daObj.%Set(node.NodeData, dynArray)
		    }
		    else
		    {
			    $$$TRACE( "  -- SET else " _ node.NodeData )
			    Do daObj.%Set(node.NodeData, dcObj)


 				set key = $ORDER(attrArray(""))
   				while (key '= "") 
   				{ 
   					$$$TRACE( "Add Attribute element:"_key_"=/"_attrArray(key))
   					Do dcObj.%Set(key, attrArray(key))
   					set key = $ORDER(attrArray(key))
   				}

			    kill attrArray

		    }



		    set prevNode = node.NodeData
    	}
	 } WHILE (node.MoveToNextSibling())
	 $$$TRACE( "ParseAllNodes: " _ daObj.%ToJSON())

	Quit daObj


	// WRITE !, "ParseChildNode: " _node.NodeData  
	$$$TRACE( "   -- ParseChildNode: NodeData="_node.NodeData)
    set stat = node.MoveToFirstChild()

	$$$TRACE("   --- First Child NODE: NodeData="_node.NodeData_" NodeId="_node.NodeId_" NodeType="_node.NodeType_" QName="_node.QName_" HasChildNodes returns "_node.HasChildNodes()_" GetNumberAttributes returns "_node.GetNumberAttributes())

	while(node.NodeType = $$$xmlWHITESPACENODE)
    {
	    set stat = node.MoveToNextSibling()
    }

	if (node.NodeType = $$$xmlELEMENTNODE)
    {

		set dcObj = ..ParseAllNodes(node, 0, listArr)
		$$$TRACE( "   *** ParseChildNode: -- from ParseAllNodes: " _ node.NodeData _ " , " _ dcObj.%ToJSON())

    }
    else
    {
	    // xmlTEXTNODE

	    set dcObj = node.NodeData

    }
	Do node.MoveToParent()
	$$$TRACE( "   ---- ParseChildNode Output: " _ dcObj _ ", Parent NodeData="_node.NodeData)
	Quit dcObj
